def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]

    result = min(v1, v2, v3)

    return {
        "value": result,
        "trace": {
            "values": [v1, v2, v3],
            "minimum": result,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
